use xiom.io;
fn peek(stack: Vec[Int]) -> Option[Int] {
  if stack.is_empty() { return None; }
  return stack.get(stack.len() - 1);
}

fn main() -> Int {
  let stack: Vec[Int] = Vec[Int].new();
  stack.push(10);
  stack.push(20);
  stack.push(30);

  match peek(stack) {
    Some(v) -> io.println(v.to_str());
    None -> io.println("empty");
  }

  while !stack.is_empty() {
    match stack.pop() {
      Some(v) -> io.println(v.to_str());
      None -> {}
    }
  }

  io.println(stack.is_empty().to_str());
  return 0;
}
